css:
html, body { font-family: "Times New Roman", Times, serif; font-weight: 420; }
.ql-editor ol { padding-left: 0; counter-reset: clause; }
.ql-editor li { list-style: none; position: relative; padding-left: 2em; margin-bottom: 8px; }
.ql-editor li > .ql-ui:before { display: inline-block; width: 1.7em; margin-left: -2em; margin-right: 0.3em; text-align: right; }
.ql-editor li[data-list=ordered]:not([class*="ql-indent"]) { counter-increment: clause; counter-reset: sub; }
.ql-editor li[data-list=ordered]:not([class*="ql-indent"]) > .ql-ui:before { content: counter(clause) ". "; }
.ql-editor li[data-list].ql-indent-1 { counter-increment: sub; margin-left: 2em; margin-bottom: 4px; }
.ql-editor li[data-list=ordered].ql-indent-1 > .ql-ui:before { content: counter(sub, lower-roman) ". "; }
.ql-editor li[data-list=bullet] > .ql-ui:before { content: "\2022"; }

