       "fieldtype": "HTML",
       "custom": 1,
       "html": "{%- set offer = frappe.get_cached_doc(\"Job Offer\", doc.job_offer) if doc.job_offer else {} -%}\n{%- macro money(v) -%}{{ frappe.utils.fmt_money(v or 0, currency=offer.currency) }}{%- endmacro -%}\n{%- set frequency = (frappe.db.get_value(\"Salary Structure\", offer.salary_structure, \"payroll_frequency\") or \"Monthly\") if offer.salary_structure else \"Monthly\" -%}\n{%- if offer.ctc_breakup %}\n<div style=\"margin-top:20px;page-break-inside:avoid;\">\n<p style=\"text-align:center;font-size:13px;font-weight:700;letter-spacing:0.08em;\">ANNEXURE A - REMUNERATION</p>\n<p>Total cost to company: {{ money(offer.ctc) }} per annum</p>\n<table style=\"width:100%;border-collapse:collapse;margin-top:10px;\">\n<thead><tr style=\"border-bottom:1px solid #1f272e;\"><th style=\"text-align:left;padding:6px 4px;\">Component</th><th style=\"text-align:right;padding:6px 4px;\">{{ frequency }}</th><th style=\"text-align:right;padding:6px 4px;\">Annual</th></tr></thead>\n<tbody>\n{%- for row in offer.ctc_breakup %}\n<tr style=\"border-bottom:1px solid #d5dae0;{% if row.is_summary %}font-weight:700;{% endif %}\"><td style=\"padding:6px 4px;\">{{ row.fixed_components }}</td><td style=\"text-align:right;padding:6px 4px;\">{{ money(row.per_cycle) }}</td><td style=\"text-align:right;padding:6px 4px;\">{{ money(row.yearly) }}</td></tr>\n{%- endfor %}\n</tbody></table>\n<p style=\"color:#6b7681;font-size:12px;margin-top:10px;\">Income tax is deducted as per applicable law and is not shown above.</p>\n</div>\n{%- endif %}\n",
       "custom_style": ""
      }
     ]
    }
   ]
  },
  {
   "label": "",
   "columns": [
    {
     "label": "",
     "fields": [
      {
